// Khởi tạo các biến nếu chưa có
let metalCount = flow.get('metalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let lastMetalState = context.get('lastMetalState') || false;
let lastOpticalState = context.get('lastOpticalState') || false;

// 1. TUYỆT ĐỐI BỎ QUA CÁC LỆNH ĐIỀU KHIỂN BĂNG TẢI, NGẮT KẾT NỐI, CLEAR LOG
if (msg.topic === "conveyor_cmd" || msg.topic === "simulate_disconnect" || msg.topic === "clear_log") {
    return null;
}

// 2. Xử lý nút Reset
if (msg.topic === "reset" || msg.payload === "reset") {
    metalCount = 0;
    totalCount = 0;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    context.set('lastMetalState', false);
    context.set('lastOpticalState', false);
    return [
        { payload: 0, topic: "metal" },     // Out 1: SP Kim loại
        { payload: 0, topic: "total" },     // Out 2: Tổng sản phẩm
        null                                // Out 3: Kích hoạt Solenoid
    ];
}

// 3. Xử lý cảm biến IN1 (kim loại) và IN2 (quang) từ Modbus RTU
let isMetal = false;
let isOptical = false;

if (msg.topic === "simulate_metal") {
    isMetal = true;
    isOptical = true;
} else if (msg.topic === "non_metal") {
    isOptical = true;
} else if (msg.topic === "" || msg.topic === "sensor" || msg.topic === "polling" || !msg.topic) {
    if (Array.isArray(msg.payload)) {
        isMetal = Boolean(msg.payload[0]);
        isOptical = (msg.payload.length > 1) ? Boolean(msg.payload[1]) : isMetal;
    } else if (typeof msg.payload === "boolean") {
        isMetal = msg.payload;
        isOptical = msg.payload;
    }
}

// SƯỜN LÊN KIM LOẠI: Cả cảm biến từ và cảm biến quang đều kích hoạt
if (isMetal && !lastMetalState) {
    context.set('lastMetalState', true);
    context.set('lastOpticalState', true);
    metalCount += 1;
    totalCount += 1;
    flow.set('metalCount', metalCount);
    flow.set('totalCount', totalCount);

    return [
        { payload: metalCount, topic: "metal" },   // Out 1: SP Kim loại
        { payload: totalCount, topic: "total" },   // Out 2: Tổng sản phẩm
        { payload: [true], topic: "trigger" }      // Out 3: Kích hoạt Solenoid
    ];
}

// SƯỜN LÊN PHI KIM: Cảm biến quang kích hoạt nhưng cảm biến từ KHÔNG kích hoạt
if (isOptical && !isMetal && !lastOpticalState) {
    context.set('lastOpticalState', true);
    totalCount += 1;
    flow.set('totalCount', totalCount);

    return [
        null,                                        // Out 1: Không có kim loại
        { payload: totalCount, topic: "non_metal" }, // Out 2: Tổng sản phẩm
        null                                         // Out 3: Không gạt Solenoid
    ];
}

if (!isMetal) context.set('lastMetalState', false);
if (!isOptical) context.set('lastOpticalState', false);

return null;

// Quản lý Trạng thái & Nhật ký SCADA tách biệt 2 mảng
let state = flow.get('scada_state') || 'STOPPED';
let statusText = flow.get('scada_statusText') || 'Hệ thống đang dừng';
let conveyorRunning = flow.get('conveyorRunning') || false;
let metalCount = flow.get('metalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let opEvents = flow.get('opEvents') || [];
let secEvents = flow.get('secEvents') || [];
let intervals = flow.get('intervals') || [];
let lastMetalTime = flow.get('lastMetalTime') || null;

let now = new Date();
let timeStr = now.toTimeString().split(' ')[0];
let soundTrigger = null;

function addOpEvent(tag, tagType, text) {
    opEvents.unshift({ time: timeStr, tag: tag, tagType: tagType, text: text });
    if (opEvents.length > 50) opEvents.pop();
    flow.set('opEvents', opEvents);
}

function addSecEvent(tag, tagType, text) {
    secEvents.unshift({ time: timeStr, tag: tag, tagType: tagType, text: text });
    if (secEvents.length > 50) secEvents.pop();
    flow.set('secEvents', secEvents);
}

// =========================================================
// MẢNG 1: BẢO MẬT & TRUY CẬP (SECURITY & AUDIT)
// =========================================================
if (msg.topic === 'user_login') {
    soundTrigger = 'chime';
    addSecEvent('ĐĂNG NHẬP', 'primary', 'Kỹ sư ' + msg.payload + ' đăng nhập vào hệ thống');
} else if (msg.topic === 'user_logout') {
    soundTrigger = 'beep';
    addSecEvent('ĐĂNG XUẤT', 'info', 'Kỹ sư ' + msg.payload + ' đã đăng xuất khỏi hệ thống');
} else if (msg.topic === 'heartbeat_status') {
    if (msg.payload === true) {
        addSecEvent('KẾT NỐI', 'success', 'Truyền thông Modbus ESP8266 ổn định (100ms)');
    } else {
        addSecEvent('TIMEOUT', 'danger', 'Mất kết nối Modbus ESP8266 (>5 giây)');
    }
}

// =========================================================
// MẢNG 2: VẬN HÀNH & THIẾT BỊ (OPERATION & ALARMS)
// =========================================================
else if (msg.topic === 'conveyor_cmd') {
    let run = Array.isArray(msg.payload) ? Boolean(msg.payload[0]) : Boolean(msg.payload);
    if (run) {
        conveyorRunning = true;
        state = 'RUNNING';
        statusText = 'Băng chuyền đang hoạt động';
        soundTrigger = 'beep';
        addOpEvent('BĂNG TẢI', 'success', 'Khởi động động cơ băng chuyền vận hành');
    } else {
        conveyorRunning = false;
        state = 'STOPPED';
        statusText = 'Băng chuyền đã dừng';
        soundTrigger = 'beep';
        addOpEvent('BĂNG TẢI', 'danger', 'Dừng động cơ băng chuyền an toàn');
    }
} else if (msg.topic === 'non_metal') {
    totalCount = flow.get('totalCount') || msg.payload;
    addOpEvent('PHI KIM', 'info', 'Cảm biến quang phát hiện phôi phi kim #' + totalCount + ' (Đi thẳng vào khay cuối)');
} else if (msg.topic === 'metal') {
    metalCount = msg.payload;
    totalCount = flow.get('totalCount') || metalCount;
    state = 'SORTING';
    statusText = 'Phát hiện phôi kim loại #' + metalCount;
    soundTrigger = 'chime';
    addOpEvent('KIM LOẠI', 'warning', 'Cảm biến IN1 phát hiện phôi kim loại #' + metalCount);

    // Tính chu kỳ thời gian (giây) giữa 2 lần phát hiện
    let curTime = Date.now();
    if (lastMetalTime) {
        let diffSec = Math.round(((curTime - lastMetalTime) / 1000) * 10) / 10;
        if (diffSec > 0.5 && diffSec < 60) {
            intervals.push(diffSec);
            if (intervals.length > 25) intervals.shift();
            flow.set('intervals', intervals);
        }
    }
    lastMetalTime = curTime;
    flow.set('lastMetalTime', lastMetalTime);
} else if (msg.topic === 'solenoid_on' || (msg.payload && msg.payload[0] === true && msg.adr === 1)) {
    state = 'SORTING';
    statusText = 'Solenoid kích hoạt đòn bẩy gạt phôi';
    soundTrigger = 'chime';
    addOpEvent('SOLENOID', 'warning', 'Kích hoạt đòn bẩy Solenoid gạt phôi kim loại');
} else if (msg.topic === 'solenoid_off' || msg.payload === false) {
    state = conveyorRunning ? 'RUNNING' : 'STOPPED';
    statusText = conveyorRunning ? 'Băng chuyền đang hoạt động' : 'Băng chuyền đã dừng';
    addOpEvent('SOLENOID', 'info', 'Thu hồi đòn bẩy Solenoid về vị trí chờ');
} else if (msg.topic === 'reset') {
    metalCount = 0;
    totalCount = 0;
    intervals = [];
    lastMetalTime = null;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    flow.set('intervals', []);
    flow.set('lastMetalTime', null);
    soundTrigger = 'beep';
    addOpEvent('RESET', 'danger', 'Đặt lại toàn bộ số đếm và chu kỳ về 0');
} else if (msg.topic === 'clear_op_log') {
    opEvents = [];
    flow.set('opEvents', []);
    addOpEvent('DỌN DẸP', 'info', 'Đã xóa nhật ký vận hành');
} else if (msg.topic === 'clear_sec_log') {
    secEvents = [];
    flow.set('secEvents', []);
    addSecEvent('DỌN DẸP', 'info', 'Đã xóa nhật ký bảo mật');
}

flow.set('scada_state', state);
flow.set('scada_statusText', statusText);
flow.set('conveyorRunning', conveyorRunning);

msg.payload = {
    state: state,
    statusText: statusText,
    conveyorRunning: conveyorRunning,
    metalCount: flow.get('metalCount') || 0,
    totalCount: flow.get('totalCount') || 0,
    opEvents: opEvents,
    secEvents: secEvents,
    intervals: intervals,
    soundTrigger: soundTrigger,
    time: timeStr
};

return msg;

// Gate kiểm tra tín hiệu Heartbeat
let isBlocked = flow.get('heartbeat_blocked') || false;

if (msg.topic === 'simulate_disconnect') {
    isBlocked = Boolean(msg.payload);
    flow.set('heartbeat_blocked', isBlocked);
    if (isBlocked) {
        // Đã ngắt: không gửi gì để node trigger hết 5s sẽ báo Timeout!
        return null;
    } else {
        // Khôi phục: gửi ngay tín hiệu ping để trigger phục hồi Connected
        return { payload: true, topic: 'heartbeat_ping' };
    }
}

// Nếu nhận heartbeat định kỳ từ inject hoặc modbus
if (!isBlocked) {
    return { payload: true, topic: 'heartbeat_ping' };
}

return null;
